function syncLabels(){const isLine=$('preset').value==='line';document.querySelector('.smart-section').hidden=isLine;for(const id of ['colorMode','colors','speckles'])$(id).closest('.field').hidden=isLine;$('corners').closest('label').hidden=isLine;$('lineSettings').hidden=$('preset').value!=='line';$('lineWidth').disabled=$('lineWidthAuto').checked;$('lineGap').disabled=$('lineSymmetry').disabled=!$('lineRefine').checked;$('lineGapOut').textContent=$('lineGap').value==='0'?'Nonaktif':$('lineGap').value+' px';$('lineWidthOut').textContent=$('lineWidthAuto').checked?'Otomatis':$('lineWidth').value+' px';for(const id of ['colors','tolerance','speckles','threshold','monoThreshold','smartTolerance'])$(id+'Out').textContent=$(id).value+((id==='tolerance'||id==='smartTolerance')?' px':id==='speckles'?' titik':'');$('threshold').disabled=$('alpha').value==='flatten';$('colors').disabled=$('preset').value==='mono'||$('colorMode').value==='auto';if($('colorMode').value==='auto'&&!['mono','line'].includes($('preset').value))$('colorsOut').textContent='Otomatis';}
