async function loadFile(file){try{await inspectRaster(file);const url=URL.createObjectURL(file);const image=new Image();try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('Gambar tidak dapat dibaca. File mungkin rusak.'));image.src=url;});setSource(image,url,file.name,file.size,false);}catch(e){URL.revokeObjectURL(url);throw e;}}catch(e){showToast(e.message);}}
