function sample(){const c=document.createElement('canvas');c.width=900;c.height=900;const ctx=c.getContext('2d');ctx.fillStyle='#f5f3e7';ctx.fillRect(0,0,900,900);ctx.fillStyle='#163e36';ctx.fillRect(80,80,360,360);ctx.fillStyle='#a6bf76';ctx.beginPath();ctx.arc(260,260,155,0,Math.PI*2);ctx.fill();ctx.fillStyle='#163e36';ctx.beginPath();ctx.arc(260,260,76,0,Math.PI*2);ctx.fill();ctx.fillStyle='#dce89f';ctx.fillRect(460,80,360,360);ctx.fillStyle='#356f57';ctx.beginPath();ctx.moveTo(460,440);ctx.lineTo(820,80);ctx.lineTo(820,440);ctx.closePath();ctx.fill();ctx.fillStyle='#c8744f';ctx.fillRect(80,460,360,360);ctx.fillStyle='#f0cf8a';for(let i=0;i<4;i++){ctx.fillRect(105+i*82,490,35,300);}ctx.fillStyle='#a6bf76';ctx.fillRect(460,460,360,360);ctx.fillStyle='#173e36';ctx.beginPath();ctx.arc(640,820,180,Math.PI,2*Math.PI);ctx.fill();ctx.beginPath();ctx.arc(640,460,180,0,Math.PI);ctx.fill();const image=new Image();image.onload=()=>{setSource(image,image.src,'geometric-study.png',0,true);convert();};image.src=c.toDataURL('image/png');}
