function fitArt(){if(!source)return;const area=$('artScroll'),maxW=Math.max(100,area.clientWidth-60),maxH=Math.max(100,area.clientHeight-90),fit=Math.min(maxW/source.width,maxH/source.height,1);$('artboard').style.width=Math.round(source.width*fit*zoom)+'px';$('artboard').style.height=Math.round(source.height*fit*zoom)+'px';$('zoomFit').textContent=Math.round(zoom*100)+'%';if(typeof refineRender==='function')refineRender();}
