function setBusy(value){busy=value;$('busy').hidden=!value;$('settings').disabled=false;$('convertBtn').hidden=value;$('cancelBtn').hidden=!value;for(const id of ['topUpload','uploadBox','outputSize'])$(id).disabled=value;}
function stopWorker(){worker?.terminate();worker=null;clearTimeout(timeout);setBusy(false);}
$('cancelBtn').onclick=()=>{clearTimeout(autoTimer);autoTimer=null;revision++;stopWorker();$('resultStatus').textContent='Dibatalkan';showToast('Konversi dibatalkan. Gambar sumber tetap tersedia.');};
function convert(){if(!source||busy)return;invalidate();setBusy(true);const rev=revision;const start=performance.now();$('busyStage').textContent='Mempersiapkan gambar…';try{const config=settings(),factor=Math.min(1,config.resolution/Math.max(source.width,source.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(source.width*factor));canvas.height=Math.max(1,Math.round(source.height*factor));const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(source.image,0,0,canvas.width,canvas.height);const image=ctx.getImageData(0,0,canvas.width,canvas.height);worker=new Worker('trace-worker.js');timeout=setTimeout(()=>{if(rev===revision){stopWorker();showToast('Proses melebihi 2 menit. Kurangi resolusi atau jumlah warna lalu coba lagi.');}},120000);worker.onmessage=async({data})=>{if(rev!==revision)return;if(data.stage){$('busyStage').textContent=data.stage;return;}if(data.error){stopWorker();showToast(data.error);return;}if(data.done){stopWorker();result={...data,config,seconds:(performance.now()-start)/1000,traceWidth:canvas.width,traceHeight:canvas.height};$('stepTrace').classList.add('active');$('stepExport').classList.add('active');$('resultStatus').textContent='Terbentuk';$('resultStatus').classList.add('ready');$('convertHint').textContent='Selesai dalam '+result.seconds.toFixed(1)+' detik. Perubahan parameter diproses otomatis.';for(const id of ['epsBtn','svgBtn','pngBtn'])$(id).disabled=false;document.querySelectorAll('[data-view]').forEach(b=>b.disabled=false);renderResult();renderPalette();setView(preferredView);await measureDifference();}};worker.onerror=e=>{if(rev!==revision)return;stopWorker();showToast('Mesin tracing gagal: '+(e.message||'Coba muat ulang halaman.'));};worker.postMessage({image,settings:config},[image.data.buffer]);}catch(e){stopWorker();showToast('Konversi gagal: '+e.message);}}
