function renderPalette(){if(!result)return;const current=result;$('palette').replaceChildren();const used=new Set(PreciseEngine.objects(result.td).map(o=>o.layer));result.td.palette.forEach((c,i)=>{if(!used.has(i))return;const hex='#'+[c.r,c.g,c.b].map(x=>Math.round(x).toString(16).padStart(2,'0')).join('');const row=document.createElement('div');row.className='palette-editor';const input=document.createElement('input');input.type='color';input.value=hex;input.setAttribute('aria-label','Pilih warna '+(i+1));const text=document.createElement('input');text.type='text';text.value=hex;text.maxLength=7;text.spellcheck=false;text.setAttribute('aria-label','Kode HEX warna '+(i+1));function apply(value){if(result!==current)return;const v=value.trim();if(!/^#[0-9a-f]{6}$/i.test(v)){text.setAttribute('aria-invalid','true');return;}text.removeAttribute('aria-invalid');input.value=v;text.value=v;current.td.palette[i]={r:parseInt(v.slice(1,3),16),g:parseInt(v.slice(3,5),16),b:parseInt(v.slice(5,7),16),a:c.a};current.stats=PreciseEngine.stats(current.td);renderResult();$('paletteNote').textContent='Palet diedit. Lihat mode Vektor untuk warna terbaru; ekspor ikut diperbarui.';}input.oninput=()=>apply(input.value);input.onchange=()=>measureDifference();text.oninput=()=>{if(/^#[0-9a-f]{6}$/i.test(text.value))apply(text.value);};text.onchange=()=>{apply(text.value);measureDifference();};text.onkeydown=e=>{if(e.key==='Enter'){apply(text.value);measureDifference();}};row.append(input,text);$('palette').append(row);});$('paletteNote').textContent='Klik kotak warna atau edit kode HEX. Perubahan terlihat di mode Vektor.';}
