async function svgImage(svg){const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Preview vektor tidak dapat dirender.'));img.src=url;});return img;}finally{URL.revokeObjectURL(url);}}
async function measureDifference(){if(!result)return;const rev=++renderRevision,current=result;try{const factor=Math.min(1,512/Math.max(source.width,source.height));const w=Math.max(1,Math.round(source.width*factor)),h=Math.max(1,Math.round(source.height*factor));const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.fillStyle='white';ctx.fillRect(0,0,w,h);ctx.drawImage(source.image,0,0,w,h);const original=ctx.getImageData(0,0,w,h).data;const img=await svgImage(current.svg);if(rev!==renderRevision||current!==result)return;ctx.fillStyle='white';ctx.fillRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);const traced=ctx.getImageData(0,0,w,h).data;let error=0;for(let i=0;i<original.length;i+=4)for(let k=0;k<3;k++)error+=Math.abs(original[i+k]-traced[i+k]);const percent=error/(w*h*3*255)*100;$('fidelity').hidden=false;$('diffValue').textContent=percent.toFixed(2)+'%';$('diffMeter').style.width=Math.max(1,100-percent)+'%';}catch(e){showToast(e.message);}}
function download(content,type,ext){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(source.name.replace(/\.(png|jpe?g)$/i,'')||'artwork')+'-vector.'+ext;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
$('epsBtn').onclick=()=>{if(result){download(result.eps,'application/postscript','eps');showToast('EPS diunduh. Periksa hasil di editor vektor sebelum submission.');}};
$('svgBtn').onclick=()=>{if(result)download(result.svg,'image/svg+xml','svg');};
$('pngBtn').onclick=async()=>{if(!result)return;const current=result,button=$('pngBtn');button.disabled=true;button.textContent='Merender…';try{const img=await svgImage(current.svg);const width=outputWidth(),height=Math.round(width*current.td.height/current.td.width);if(width*height>40000000)throw Error('Preview terlalu besar. Pilih sisi ekspor 4.000 px.');const c=document.createElement('canvas');c.width=width;c.height=height;c.getContext('2d').drawImage(img,0,0,width,height);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw Error('Preview PNG gagal dibuat.');if(current===result)download(blob,'image/png','png');}catch(e){showToast(e.message);}finally{button.disabled=!result;button.textContent='Preview PNG';}};
$('guideBtn').onclick=()=>$('guideDialog').showModal();$('policyBtn').onclick=()=>$('policyDialog').showModal();document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});syncLabels();


